import json
import os

from huggingface_hub import scan_cache_dir

from .decider import CHECKPOINT

# Generated by `basic-eval` / `experiment-generation`; matched by the *_evaluation.json /
# *_experiment.json patterns in .gitignore.
GENERATED_FILES = ["basic_evaluation.json", "generated_experiment.json"]

# strands_decider.modeling.CONFIG_NAME / LEGACY_CONFIG_NAME.
_CONFIG_NAMES = ("strands_decider_config.json", "hobson_config.json")


def _revision_hashes(cache_info, repo_id: str) -> list[str]:
    return [
        revision.commit_hash
        for repo in cache_info.repos
        if repo.repo_id == repo_id
        for revision in repo.revisions
    ]


def _base_model_of(cache_info, repo_id: str) -> str | None:
    for repo in cache_info.repos:
        if repo.repo_id != repo_id:
            continue
        for revision in repo.revisions:
            for name in _CONFIG_NAMES:
                config_file = revision.snapshot_path / name
                if config_file.exists():
                    return json.loads(config_file.read_text())["base_model"]
    return None


def run() -> None:
    print("Hugging Face cache:")
    cache_info = scan_cache_dir()

    base_model = _base_model_of(cache_info, CHECKPOINT)
    repo_ids = [CHECKPOINT] + ([base_model] if base_model else [])
    hashes = [h for repo_id in repo_ids for h in _revision_hashes(cache_info, repo_id)]

    for repo_id in repo_ids:
        status = "removing" if _revision_hashes(cache_info, repo_id) else "not cached"
        print(f"  {repo_id}: {status}")

    if hashes:
        cache_info.delete_revisions(*hashes).execute()

    print("Generated output files:")
    for name in GENERATED_FILES:
        if os.path.exists(name):
            os.remove(name)
            print(f"  {name}: removed")
        else:
            print(f"  {name}: not present")
